/**
 * The world's baked implicit bodies (D-ART-014), decoded on first use: fledglings, Thicket creatures, the Roc and the
 * structures' bird statues. Generated by tests/anim/bake-world.ts from world-bodies.ts.
 */
import { decodeSkin } from './skin';
import type { SkinLevel } from './skin';
import { SKIN as chick } from './data/world/chick';
import { SKIN as beetle } from './data/world/beetle';
import { SKIN as weasel } from './data/world/weasel';
import { SKIN as rat } from './data/world/rat';
import { SKIN as toad } from './data/world/toad';
import { SKIN as badger } from './data/world/badger';
import { SKIN as cub } from './data/world/cub';
import { SKIN as hawk } from './data/world/hawk';
import { SKIN as heron } from './data/world/heron';
import { SKIN as owlHead } from './data/world/owlHead';
import { SKIN as raven } from './data/world/raven';
import { SKIN as greatOwl } from './data/world/greatOwl';
import { SKIN as roc } from './data/world/roc';
import { SKIN as rocHead } from './data/world/rocHead';
import type { WorldBody } from './world-bodies';

export const WORLD_SKINS: Readonly<Record<WorldBody, string>> = { chick, beetle, weasel, rat, toad, badger, cub, hawk, heron, owlHead, raven, greatOwl, roc, rocHead };

/** A world body's four baked levels (finest first). */
export const worldSkin = (name: WorldBody): readonly SkinLevel[] => decodeSkin(WORLD_SKINS[name]);
